import java.sql.*;
import java.nio.file.*;
public class Check {
    public static void main(String[] args) throws Exception {
        String file=Files.readString(Path.of("hello.db2")).strip();
        String directive="--#SET TERMINATOR @";
        if(!file.startsWith(directive) || !file.endsWith("@")) throw new IllegalArgumentException(file);
        String create=file.substring(directive.length(),file.length()-1);
        try(Connection con=DriverManager.getConnection("jdbc:hsqldb:mem:corpus","SA","");
            Statement s=con.createStatement()){
            s.execute(create);
            try(CallableStatement call=con.prepareCall("CALL corpus_greeting(?)")){
                call.registerOutParameter(1,Types.VARCHAR);
                call.execute();
                System.out.println(call.getString(1));
            }
        }
    }
}
